require_once __DIR__.'/includes/bootstrap.php';require_login();$id=(int)($_GET['id']??0);$q=db()->prepare('SELECT s.*,u.full_name,p.method,p.amount payment_amount FROM sales s JOIN users u ON u.id=s.cashier_id LEFT JOIN payments p ON p.sale_id=s.id WHERE s.id=?');$q->execute([$id]);$sale=$q->fetch();if(!$sale){http_response_code(404);exit('Receipt not found.');}$q=db()->prepare('SELECT * FROM sale_items WHERE sale_id=?');$q->execute([$id]);$items=$q->fetchAll();$pageTitle='Receipt';require 'includes/header.php';?>
<div class="receipt-actions"><a href="pos.php" class="btn secondary">＋ New sale</a><button onclick="window.print()" class="btn primary">Print receipt</button></div><div class="receipt-paper"><div class="receipt-center"><div class="brand-mark">T</div><h2>TMC DASH 'N' DINE</h2><p>Thank you for your purchase!</p></div><hr><div class="receipt-meta"><span>Receipt: <?=e($sale['receipt_number'])?></span><span><?=date('d/m/Y H:i',strtotime($sale['created_at']))?></span><span>Cashier: <?=e($sale['full_name'])?></span></div><hr><table><thead><tr><th>Item</th><th>Qty</th><th>Price</th><th>Total</th></tr></thead><tbody><?php foreach($items as $it):?><tr><td><?=e($it['product_name'])?></td><td><?=e($it['quantity'])?></td><td><?=money($it['unit_price'])?></td><td><?=money($it['line_total'])?></td></tr><?php endforeach;?></tbody></table><hr><div class="total-line"><span>Subtotal</span><b><?=money($sale['subtotal'])?></b></div><div class="total-line grand"><span>TOTAL</span><strong><?=money($sale['total'])?></strong></div><div class="total-line"><span>Payment</span><b><?=e(strtoupper($sale['method']??'—'))?></b></div><div class="receipt-center receipt-thanks">Please come again.</div></div><?php require 'includes/footer.php';?>
